const CSS = `
:root{color-scheme:dark;--bg:#07111f;--panel:#0d1b2e;--line:#243b57;--text:#ecf5ff;--muted:#97abc3;--blue:#55b8ff;--mint:#59e1c4;--danger:#ff7185;--amber:#ffc96b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#123257 0,transparent 34rem),var(--bg);color:var(--text);min-height:100vh}a{color:var(--blue)}.wrap{width:min(1120px,calc(100% - 32px));margin:auto}.top{display:flex;align-items:center;justify-content:space-between;padding:24px 0}.brand{display:flex;align-items:center;gap:12px;font-weight:800;letter-spacing:.05em}.mark{width:38px;height:38px;border:1px solid #68d6ff80;border-radius:12px;background:linear-gradient(145deg,#163f69,#0e233a);display:grid;place-items:center;box-shadow:0 0 28px #32b8ff2e}.mark:after{content:"13";color:var(--mint)}.muted{color:var(--muted)}.hero{padding:72px 0 48px}.eyebrow{color:var(--mint);font:700 12px ui-monospace,monospace;letter-spacing:.18em;text-transform:uppercase}.hero h1{font-size:clamp(38px,8vw,78px);line-height:.98;max-width:850px;margin:16px 0 24px}.hero p{font-size:18px;line-height:1.9;max-width:760px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:linear-gradient(160deg,#10233aee,#0a1728ee);border:1px solid var(--line);border-radius:18px;padding:22px;box-shadow:0 18px 60px #0003}.card h2,.card h3{margin-top:0}.btn,button{border:0;border-radius:11px;padding:11px 16px;font-weight:750;cursor:pointer;background:linear-gradient(135deg,var(--blue),var(--mint));color:#02111d;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn.secondary,button.secondary{background:#142a43;color:var(--text);border:1px solid var(--line)}button.danger{background:#3d1721;color:#ffdce2;border:1px solid #73303f}button:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;gap:10px;flex-wrap:wrap}.app-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:18px;padding-bottom:48px}.full{grid-column:1/-1}label{display:grid;gap:7px;color:var(--muted);font-size:13px}input,select{width:100%;background:#071422;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:11px 12px;outline:none}input:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px #55b8ff1c}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.span-2{grid-column:1/-1}.check{display:flex;align-items:flex-start;gap:10px}.check input{width:auto;margin-top:3px}.list{display:grid;gap:10px}.item{border:1px solid var(--line);background:#091725;border-radius:12px;padding:14px}.item-head{display:flex;justify-content:space-between;gap:10px}.tag{font:700 11px ui-monospace,monospace;padding:5px 8px;border-radius:999px;background:#16324d;color:var(--blue)}.tag.ready{background:#113b35;color:var(--mint)}.tag.failed{background:#431d27;color:#ff9aaa}.tag.revoked{background:#2e3037;color:#bbc1c9}pre{white-space:pre-wrap;word-break:break-all;background:#050d16;border:1px solid var(--line);padding:14px;border-radius:11px;color:#bedcff;direction:ltr;text-align:left}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.notice{border-right:3px solid var(--amber);padding:12px 14px;background:#33281255;border-radius:9px;color:#ffe1a7}.error{border-right-color:var(--danger);background:#3a151d66;color:#ffc3cc}.success{border-right-color:var(--mint);background:#12352f66;color:#bdfff1}.kpis{display:flex;gap:18px;flex-wrap:wrap}.kpi strong{display:block;font-size:22px}.footer{padding:30px 0 50px;color:var(--muted);font-size:13px}details{margin:12px 0 16px;border:1px solid var(--line);border-radius:11px;padding:12px}summary{cursor:pointer;font-weight:750;color:var(--mint)}ol{line-height:1.9;margin-bottom:0}@media(max-width:820px){.grid,.app-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.span-2,.full{grid-column:auto}.hero{padding-top:38px}.top{align-items:flex-start}.top .muted{display:none}}
`;

function shell(documentBody: string, nonce: string, title: string): string {
  return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style nonce="${nonce}">${CSS}</style></head><body>${documentBody}</body></html>`;
}

export function logoSvg(): Response {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" role="img" aria-label="V13"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#55b8ff"/><stop offset="1" stop-color="#59e1c4"/></linearGradient></defs><rect width="512" height="512" rx="112" fill="#07111f"/><rect x="28" y="28" width="456" height="456" rx="92" fill="none" stroke="url(#g)" stroke-width="20"/><text x="256" y="318" text-anchor="middle" font-family="system-ui,sans-serif" font-size="190" font-weight="800" fill="url(#g)">13</text></svg>`;
  return new Response(svg, {
    headers: {
      "Content-Type": "image/svg+xml; charset=utf-8",
      "Cache-Control": "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

function botUsername(env: Env): string {
  return /^[A-Za-z0-9_]{5,64}$/u.test(env.BOT_USERNAME) ? env.BOT_USERNAME : "replace_me_bot";
}

function botDeepLink(env: Env, arg: string): string {
  return `https://t.me/${botUsername(env)}?start=${encodeURIComponent(arg)}`;
}

