export function legalPage(kind: "privacy" | "terms"): Response {
  const nonce = requestNonce();
  const privacy = kind === "privacy";
  const title = privacy ? "حریم خصوصی V13" : "شرایط استفاده V13";
  const content = privacy
    ? `<h1>حریم خصوصی</h1><p class="muted">V13 شناسهٔ تلگرام، نام نمایشی، شناسهٔ resourceهای مجاز Cloudflare، نسخهٔ موقت و رمز‌شدهٔ Scoped API Token، وضعیت استقرار و گزارش سلامت VPS را فقط برای ارائهٔ سرویس نگه می‌دارد. Cloudflare API Token و داده‌های دسترسی استقرار با AES-256-GCM رمز می‌شوند؛ Token پس از پایان، شکست، لغو یا انقضای مهلت از پایگاه‌دادهٔ V13 پاک می‌شود. توکن نشست، اشتراک و Agent فقط به‌شکل هش قابل مقایسه نگه‌داری می‌شوند، مگر نسخهٔ لازم برای بازیابی اشتراک که داخل envelope رمز‌شده قرار دارد.</p><p class="muted">Cloudflare API Token یا رمز VPS نباید در تلگرام، چت، اسکرین‌شات یا خط فرمان ارسال شود. حذف نسخهٔ ذخیره‌شده در V13، Token اصلی را در Cloudflare باطل نمی‌کند؛ پس از پایان کار می‌توانید آن را از My Profile → API Tokens حذف کنید.</p>`
    : `<h1>شرایط استفاده</h1><p class="muted">فقط روی حساب‌ها، دامنه‌ها و سرورهایی که مالک آن هستید یا مجوز روشن مدیریتشان را دارید از V13 استفاده کنید. مسئولیت رعایت قوانین محل استفاده، شرایط ارائه‌دهندگان و جلوگیری از سوءاستفاده بر عهدهٔ بهره‌بردار است.</p><p class="muted">کیفیت و دسترس‌پذیری به شبکه، مسیر بین‌الملل، Cloudflare و VPS وابسته است. V13 اتصال در قطع کامل مسیر ارتباطی را تضمین نمی‌کند.</p>`;
  const body = `<div class="wrap"><header class="top"><div class="brand"><span class="mark"></span><span>V13</span></div><a class="btn secondary" href="/">بازگشت</a></header><main class="card">${content}</main><footer class="footer">آخرین بازبینی: ۲۰۲۶-۰۹-۱۰</footer></div>`;
  return html(shell(body, nonce, title), nonce);
}

export function appPage(principal: SessionPrincipal): Response {
  const nonce = requestNonce();
  const safeName = escapeHtml(principal.displayName);
  const body = `<div class="wrap"><header class="top"><div class="brand"><span class="mark"></span><span>V13 / CONTROL PLANE</span></div><div class="actions"><span class="muted">${safeName}</span><form method="post" action="/logout"><button class="secondary" type="submit">خروج</button></form></div></header><main class="app-grid"><section class="card"><div class="eyebrow">Least-privilege Cloudflare access</div><h2>اتصال با Scoped API Token</h2><p class="muted">دکمهٔ زیر فرم رسمی Cloudflare را با نام و سه دسترسی لازم از قبل آماده می‌کند. در Cloudflare فقط حساب و یک دامنهٔ مشخص را انتخاب، Token را تأیید و کپی کنید؛ سپس به همین صفحه برگردید.</p><div class="actions"><a class="btn" target="_blank" rel="noopener noreferrer" href="https://dash.cloudflare.com/profile/api-tokens?permissionGroupKeys=%5B%7B%22key%22%3A%22workers_scripts%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22dns%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22zone%22%2C%22type%22%3A%22read%22%7D%5D&amp;accountId=%2A&amp;zoneId=all&amp;name=V13%20Temporary%20Provisioning">ساخت Token آماده در Cloudflare</a></div><details><summary>نمایش جزئیات دسترسی‌ها</summary><ol class="muted"><li>Account → Workers Scripts → Edit — از قبل تنظیم شده</li><li>Zone → DNS → Edit — از قبل تنظیم شده</li><li>Zone → Zone → Read — از قبل تنظیم شده</li><li>Account Resources: فقط حساب موردنظر را انتخاب کنید.</li><li>Zone Resources: فقط یک Zone مشخص را انتخاب کنید.</li><li>Client IP Filtering را خالی بگذارید؛ Worker خروجی ثابت ندارد.</li></ol></details><form id="api-token-form" class="form-grid" autocomplete="off"><label class="span-2">Scoped API Token<input name="apiToken" type="password" required minlength="20" maxlength="256" autocomplete="new-password" dir="ltr" placeholder="فقط در این فرم HTTPS وارد کنید"></label><div class="span-2 actions"><button type="submit">بررسی دسترسی و اتصال موقت</button></div></form><div id="connection-result"></div><div class="notice">V13 فعال‌بودن Token، دسترسی Zone/DNS/Workers و محدودبودن آن به یک Zone را بدون تغییر resource بررسی می‌کند. نسخهٔ رمز‌شده حداکثر دو ساعت نگه‌داری و پس از پایان یا خطا پاک می‌شود. حذف محلی Token را در Cloudflare باطل نمی‌کند.</div><div id="connections" class="list"></div></section><section class="card"><div class="eyebrow">Deployment status</div><h2>استقرارها</h2><div id="deployments" class="list"><span class="muted">در حال بارگذاری…</span></div></section><section class="card full"><div class="eyebrow">Provision a real node</div><h2>ساخت استقرار جدید</h2><form id="deploy-form" class="form-grid"><label>اتصال Cloudflare<select name="connectionId" id="connection-select" required><option value="">ابتدا Cloudflare را موقت متصل کنید</option></select></label><label>حساب Cloudflare<select name="accountId" id="account-select" required><option value="">انتخاب حساب</option></select></label><label>Zone فعال<select name="zoneId" id="zone-select" required><option value="">انتخاب Zone</option></select></label><label>نام Worker<input name="workerName" required placeholder="v13-my-node" pattern="[a-z][a-z0-9-]{1,62}[a-z0-9]"></label><label>زیردامنهٔ اشتراک Worker<input name="workerHostname" required placeholder="sub.example.com" dir="ltr"></label><label>زیردامنهٔ مستقیم VPS<input name="nodeHostname" required placeholder="node.example.com" dir="ltr"></label><label>IPv4 عمومی VPS<input name="vpsIpv4" required placeholder="1.2.3.4" dir="ltr"></label><label>ایمیل ACME<input name="acmeEmail" type="email" required placeholder="admin@example.com" dir="ltr"></label><label>مقصد handshake برای Reality<input name="realityServerName" required value="www.microsoft.com" dir="ltr"></label><label class="check"><input name="enableUfw" type="checkbox"><span>UFW را خودکار فعال کن. فقط وقتی انتخاب کنید که تنظیم SSH فعلی را می‌دانید؛ پورت تشخیص‌داده‌شدهٔ SSH، پورت انتخابی VLESS روی TCP/443 یا TCP/8443 و Hysteria2 روی UDP/443 باز می‌شوند. اگر UFW از قبل فعال باشد، فقط همین Ruleهای لازم افزوده می‌شوند.</span></label><div class="span-2 actions"><button type="submit">شروع provisioning</button></div></form><div id="result"></div></section><section class="card full"><div class="eyebrow">Selected deployment</div><h2>جزئیات امن</h2><div id="details" class="muted">یک استقرار را از فهرست انتخاب کنید.</div></section><section class="card full"><div class="notice">VLESS Reality به‌صورت خودکار TCP/443 یا هنگام اشغال‌بودن آن TCP/8443 را انتخاب می‌کند؛ Hysteria2 روی UDP/443 باقی می‌ماند. دامنهٔ node باید DNS-only باشد؛ Workflow آن را خودکار می‌سازد. هیچ سازوکاری نمی‌تواند در نبود کامل مسیر ارتباطی تا سرور خارجی، اتصال را تضمین کند.</div></section></main></div>`;
  const script = `
const $=s=>document.querySelector(s);const esc=v=>String(v??"");
async function api(url,options={}){const r=await fetch(url,{...options,headers:{"Content-Type":"application/json",...(options.headers||{})}});const j=await r.json().catch(()=>({error:{message:"پاسخ نامعتبر"}}));if(!r.ok)throw new Error(j.error?.message||"خطای درخواست");return j}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
async function loadConnections(){const j=await api('/api/v1/cloudflare/connections');const box=$('#connections'),sel=$('#connection-select');box.textContent='';sel.innerHTML='<option value="">انتخاب اتصال</option>';for(const c of j.connections){const label=c.resource_zone_name||'Cloudflare connection',d=node('div',undefined,'item');d.append(node('strong',label));const expires=c.expires_at?new Date(c.expires_at).toLocaleString('fa-IR'):'نامشخص';d.append(node('div',(c.auth_type==='api_token'?'Scoped API Token · انقضای نگهداری: '+expires:'اتصال قدیمی'),'muted'));const off=node('button','پاک‌کردن نسخهٔ ذخیره‌شده','danger');off.type='button';off.onclick=async()=>{if(!confirm('نسخهٔ رمز‌شده از V13 پاک شود؟ این کار Token اصلی را در Cloudflare حذف نمی‌کند.'))return;try{await api('/api/v1/cloudflare/connections/'+c.id+'/disconnect',{method:'POST',body:'{}'});show('نسخهٔ ذخیره‌شده از V13 پاک شد.');await loadConnections()}catch(e){show(e.message,'error')}};d.append(off);box.append(d);const o=node('option',label);o.value=c.id;sel.append(o)}if(j.connections.length===1){sel.value=j.connections[0].id;await loadAccounts()}if(!j.connections.length)box.append(node('div','هنوز Scoped API Token موقتی ثبت نشده است.','muted'))}
async function loadAccounts(){const c=$('#connection-select').value,a=$('#account-select'),z=$('#zone-select');a.innerHTML='<option value="">در حال بارگذاری…</option>';z.innerHTML='<option value="">انتخاب Zone</option>';if(!c)return;try{const j=await api('/api/v1/cloudflare/accounts?connectionId='+encodeURIComponent(c));a.innerHTML='<option value="">انتخاب حساب</option>';for(const x of j.accounts){const o=node('option',x.name);o.value=x.id;a.append(o)}}catch(e){show(e.message,'error')}}
async function loadZones(){const c=$('#connection-select').value,a=$('#account-select').value,z=$('#zone-select');z.innerHTML='<option value="">در حال بارگذاری…</option>';if(!c||!a)return;try{const j=await api('/api/v1/cloudflare/zones?connectionId='+encodeURIComponent(c)+'&accountId='+encodeURIComponent(a));z.innerHTML='<option value="">انتخاب Zone</option>';for(const x of j.zones){const o=node('option',x.name);o.value=x.id;z.append(o)}}catch(e){show(e.message,'error')}}
function tagClass(s){return 'tag '+(s==='ready'?'ready':s==='failed'?'failed':s==='revoked'?'revoked':'')}
async function loadDeployments(){const j=await api('/api/v1/deployments'),box=$('#deployments');box.textContent='';for(const d of j.deployments){const i=node('button',undefined,'item secondary');i.type='button';const h=node('div',undefined,'item-head');h.append(node('strong',d.worker_name));h.append(node('span',d.status,tagClass(d.status)));i.append(h);i.append(node('div',d.worker_hostname+' · '+d.node_hostname,'muted'));i.onclick=()=>details(d.id);box.append(i)}if(!j.deployments.length)box.append(node('span','هنوز استقراری وجود ندارد.','muted'))}
function showIn(selector,message,kind='success'){const r=$(selector);r.textContent='';r.append(node('div',message,'notice '+kind))}
function show(message,kind='success'){showIn('#result',message,kind)}
function showConnection(message,kind='success'){showIn('#connection-result',message,kind)}
function commandBlock(parent,title,value){parent.append(node('strong',title));parent.append(node('pre',value))}
function secretBlock(parent,title,value){const root=node('div',undefined,'item');root.append(node('strong',title));const input=node('input');input.type='password';input.readOnly=true;input.value=value;input.dir='ltr';input.setAttribute('aria-label',title);root.append(input);const actions=node('div',undefined,'actions');const copy=node('button','کپی','secondary');copy.type='button';copy.onclick=async()=>{try{await navigator.clipboard.writeText(value);copy.textContent='کپی شد'}catch{input.type='text';input.select();document.execCommand('copy');input.type='password';copy.textContent='کپی شد'}};const reveal=node('button','نمایش موقت','secondary');reveal.type='button';reveal.onclick=()=>{input.type=input.type==='password'?'text':'password';reveal.textContent=input.type==='password'?'نمایش موقت':'مخفی‌کردن'};actions.append(copy,reveal);root.append(actions);parent.append(root)}
function renderBootstrap(b,id){const root=node('div',undefined,'item');root.append(node('h3','اسکریپت یک‌بارمصرف VPS'));root.append(node('div','توکن فقط در فرمان دریافت نشان داده می‌شود؛ فرمان بررسی آن را به‌صورت خودکار مخفی می‌کند. چهار فرمان را به‌ترتیب اجرا کنید.','notice'));commandBlock(root,'۱) دریافت',b.downloadCommand);commandBlock(root,'۲) بررسی',b.inspectCommand);commandBlock(root,'۳) اجرا',b.executeCommand);commandBlock(root,'۴) حذف فایل',b.eraseCommand);$('#result').textContent='';$('#result').append(root)}
async function details(id){const box=$('#details');box.textContent='در حال بارگذاری…';try{const j=await api('/api/v1/deployments/'+id);box.textContent='';const d=j.deployment;box.append(node('div',d.workerName+' — '+d.status,'item'));if(j.subscriptions){box.append(node('div','لینک‌های خصوصی به‌طور پیش‌فرض مخفی‌اند. فقط با دکمهٔ کپی وارد برنامهٔ کلاینت کنید.','notice'));for(const [name,url] of Object.entries(j.subscriptions))secretBlock(box,name,url)}const actions=node('div',undefined,'actions');if(['queued','preparing','awaiting_agent','failed'].includes(d.status)){const rotate=node('button','صدور Bootstrap جدید','secondary');rotate.onclick=async()=>{try{const x=await api('/api/v1/deployments/'+id+'/bootstrap-token',{method:'POST',body:'{}'});renderBootstrap(x.bootstrap,id)}catch(e){show(e.message,'error')}};actions.append(rotate)}if(['agent_ready','failed'].includes(d.status)){const retry=node('button','تلاش مجدد Workflow','secondary');retry.onclick=async()=>{try{await api('/api/v1/deployments/'+id+'/retry',{method:'POST',body:JSON.stringify({connectionId:$('#connection-select').value||undefined})});show('Workflow جدید آغاز شد.');loadDeployments()}catch(e){show(e.message,'error')}};actions.append(retry)}if(d.status==='ready'){const rotateSub=node('button','چرخاندن لینک خصوصی','secondary');rotateSub.onclick=async()=>{const connectionId=$('#connection-select').value;if(!connectionId){showConnection('ابتدا یک Scoped API Token موقت متصل کنید.','error');return}rotateSub.disabled=true;try{await api('/api/v1/deployments/'+id+'/subscription-token',{method:'POST',body:JSON.stringify({connectionId})});await loadConnections();await details(id)}catch(e){show(e.message,'error')}finally{rotateSub.disabled=false}};actions.append(rotateSub)}if(d.status!=='revoked'){const revoke=node('button','ابطال اشتراک','danger');revoke.onclick=async()=>{if(!confirm('اشتراک این استقرار باطل شود؟'))return;try{await api('/api/v1/deployments/'+id+'/revoke',{method:'POST',body:JSON.stringify({connectionId:$('#connection-select').value||undefined})});show('ابطال آغاز شد.');loadDeployments()}catch(e){show(e.message,'error')}};actions.append(revoke)}box.append(actions)}catch(e){box.textContent=e.message}}
$('#api-token-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type="submit"]'),f=new FormData(form);submit.disabled=true;try{await api('/api/v1/cloudflare/api-token',{method:'POST',body:JSON.stringify({apiToken:f.get('apiToken')})});form.reset();showConnection('Scoped API Token بررسی و اتصال موقت ساخته شد.');await loadConnections()}catch(err){showConnection(err.message,'error')}finally{submit.disabled=false}});$('#connection-select').addEventListener('change',loadAccounts);$('#account-select').addEventListener('change',loadZones);$('#deploy-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body=Object.fromEntries(f.entries());body.enableUfw=f.get('enableUfw')==='on';try{show('در حال بررسی و آغاز Workflow…');const j=await api('/api/v1/deployments',{method:'POST',body:JSON.stringify(body)});renderBootstrap(j.bootstrap,j.deploymentId);loadDeployments()}catch(err){show(err.message,'error')}});Promise.all([loadConnections(),loadDeployments()]).catch(e=>show(e.message,'error'));
`;
  const document = shell(`${body}<script nonce="${nonce}">${script}</script>`, nonce, "پنل V13");
  return html(document, nonce);
}
